const r=$input.first().json||{};
const f=r.fields||r;
const name=f['Client']||'';
return [{ json: {
  clientName: name,
  clientRecId: r.id||$('Parse Play').first().json.client||'',
  clientSlug: String(name).toLowerCase().replace(/[^a-z0-9]/g,''),
  slackChannel: f['Slack Channel ID']||'',
  base: f['Clayroots Base ID']||''
}}];

// Filter & Qualify Jobs: 100 scraped job posts in, one row per qualified company out, every
// drop counted by reason. The full job record rides on the company row so the writer can
// stamp it on every contact. _stats on the first row feeds Build Run Log.
//
// Drops, in order: country, staffing (name / poster title / industry), body shop, headcount,
// no domain, duplicate domain, already worked. An unknown headcount passes on purpose: a blank
// LinkedIn count is not a large company, and the downstream contact calls are capped anyway.
const cfg=$('Parse Play').first().json;
let items=$('Get Scraped Jobs').all().map(i=>i.json);
if(items.length===1&&Array.isArray(items[0])) items=items[0];
items=items.filter(j=>j&&(j.companyName||j.companyWebsite||j.title));
const worked=new Set($('Get Worked Domains').all().map(i=>{ const j=i.json||{}; const d=(j.fields&&j.fields.Domain)||j.Domain||''; return String(d).toLowerCase().trim(); }).filter(Boolean));

const badName=['staffing','recruit','headhunt','talent acquisition','executive search','sourcer','consulting','outsourcing'];
const badIndustry=['staffing','recruiting','executive search','venture capital','private equity','venture'];
const has=(s,list)=>{ s=String(s||'').toLowerCase(); return list.some(w=>s.includes(w)); };

// Body-shop test: a real employer names itself in its own post ("Fortreum is seeking...",
// "About IO River"). A staffing firm pastes a bare requirements list for a client it never
// names. Verified on the 2026-08-20 dataset: 6/6. Employer-brand phrases are the second tell.
const LEGAL=/\b(inc|llc|ltd|corp|corporation|co|company|solutions|technologies|technology|group|systems|services|consulting)\b/g;
const BRAND=['equal opportunity','401(k)','401k','we offer','about us','who we are','our team','our mission','our company','join us','benefits'];
function looksLikeBodyShop(j){
  const desc=String(j.descriptionText||'');
  if(!desc) return false;
  const d=desc.toLowerCase();
  const core=String(j.companyName||'').toLowerCase().replace(LEGAL,' ').replace(/[^a-z0-9]+/g,' ').trim().split(/\s+/).filter(w=>w.length>=3)[0]||'';
  if(core&&d.includes(core)) return false;
  if(BRAND.some(w=>d.includes(w))) return false;
  return true;
}

const drops={country:0,staffing_name:0,staffing_industry:0,body_shop:0,headcount:0,no_domain:0,duplicate:0,worked:0};
const seen=new Set();
const out=[];
for(const j of items){
  const country=(j.companyAddress&&j.companyAddress.addressCountry)||'';
  if(country&&country!==cfg.country){ drops.country++; continue; }
  if(has(j.companyName,badName)||has(j.jobPosterTitle,badName)){ drops.staffing_name++; continue; }
  if(has(j.industries,badIndustry)){ drops.staffing_industry++; continue; }
  if(looksLikeBodyShop(j)){ drops.body_shop++; continue; }
  const emp=Number(j.companyEmployeesCount||0);
  if(emp>cfg.max_headcount){ drops.headcount++; continue; }
  const domain=String(j.companyWebsite||'').toLowerCase().replace('https://','').replace('http://','').replace('www.','').split('?')[0].split('#')[0].split('/')[0].trim();
  if(!domain){ drops.no_domain++; continue; }
  if(seen.has(domain)){ drops.duplicate++; continue; }
  if(worked.has(domain)){ drops.worked++; continue; }
  seen.add(domain);
  out.push({ json: {
    domain,
    company: j.companyName||'',
    headcount: emp,
    country: country||cfg.country,
    company_linkedin: j.companyLinkedinUrl||'',
    company_website: j.companyWebsite||'',
    job: {
      id: String(j.id||''),
      title: j.title||'',
      link: j.link||'',
      posted_at: j.postedAt||'',
      description: j.descriptionText||'',
      seniority: j.seniorityLevel||'',
      function: j.jobFunction||'',
      employment_type: j.employmentType||'',
      industries: j.industries||'',
      applicants: Number(j.applicantsCount)||null,
      salary: j.salary||'',
      poster_name: j.jobPosterName||'',
      poster_title: j.jobPosterTitle||'',
      poster_linkedin: j.jobPosterProfileUrl||''
    }
  }});
}
const stats={ jobs_in: items.length, qualified: out.length, drops };
if(!out.length) return [{ json: { _empty:true, _stats:stats } }];
out[0].json._stats=stats;
return out;

// Build Intent Leads: one row per contact at an ICP-approved company, carrying the contact,
// the job that triggered the signal, the company's DiscoLike firmographics, the ICP reason,
// the first-hire verdict and the tier's campaign.
//
// Sources in the builders' order: ContaGen (DiscoLike /contacts/discover) every contact kept,
// then Supersoniq NET-NEW ONLY on Contact Key (first+last+domain). Provider items are
// {statusCode, body} (fullResponse + neverError) aligned by index to Contact Calls.
//
// People gate: a contact's actual title must contain one of the play's title terms and none
// of its never terms. Titles are normalised first (Chief Executive Officer -> ceo, Vice
// President -> vp) so a term written short still catches the long form. Nothing else.
// Tier: the play's rules in order, first match wins, stamped as Target Campaign.
// Company names go out raw; the Clean Fields helper writes Company / company_clean next.
const cfg=$('Parse Play').first().json;
const titleCase=(s)=>String(s).replace(/\w\S*/g,t=>t.charAt(0).toUpperCase()+t.slice(1).toLowerCase());
const cleanFirst=(f)=>{if(!f)return'';let n=String(f).split(',')[0].trim().split(/\s+/)[0]||'';n=n.replace(/[^A-Za-z\-']/g,'');return n?n.charAt(0).toUpperCase()+n.slice(1).toLowerCase():'';};
const cleanLast=(f)=>{if(!f)return'';let p=String(f).split(',')[0].trim().split(/\s+/);if(p.length<2)return'';return titleCase(p.slice(1).join(' ').replace(/[^A-Za-z\-'\s]/g,'').trim());};
const join=(a)=>Array.isArray(a)?a.filter(Boolean).join(', '):'';
const kv=(o)=>o&&typeof o==='object'?Object.entries(o).map(([k,v])=>k+':'+(typeof v==='number'?v.toFixed(2):v)).join(', '):'';
const firstPhone=(p)=>Array.isArray(p)&&p.length?String((p[0]&&p[0].phone)||p[0]||''):'';
const linkedinOf=(urls)=>Array.isArray(urls)?(urls.find(u=>/linkedin\.com\/in\//i.test(u))||''):'';
const body=(it)=>{ const j=(it&&it.json)||{}; if(j.statusCode!==undefined) return { status:Number(j.statusCode)||0, body:(j.body===undefined?null:j.body) }; return { status: j.error?0:200, body:j }; };
const parse=(b)=>{ if(typeof b!=='string') return b; try{ return JSON.parse(b); }catch(e){ return null; } };
const why=(b,raw)=>{ const m=b&&typeof b==='object'?(b.detail||b.error||b.message):null; const s=m?String(typeof m==='object'?JSON.stringify(m):m):(typeof raw==='string'?raw:(raw?JSON.stringify(raw):'')); return String(s||'empty body').slice(0,120); };

// Title normalisation: universal vocabulary, not client logic.
const SYN=[[/chief executive officer/g,'ceo'],[/chief technology officer|chief technical officer/g,'cto'],[/chief operating officer/g,'coo'],[/chief financial officer/g,'cfo'],[/chief information officer/g,'cio'],[/chief product officer/g,'cpo'],[/chief revenue officer/g,'cro'],[/chief marketing officer/g,'cmo'],[/senior vice president|executive vice president/g,'svp'],[/vice president/g,'vp'],[/co[\s-]*founder/g,'co-founder'],[/\bsr\.?\b/g,'senior'],[/&/g,'and'],[/\s+of\s+/g,' '],[/[^a-z0-9\- ]+/g,' '],[/\s+/g,' ']];
const norm=(t)=>{ let s=String(t||'').toLowerCase(); for(const [re,rep] of SYN) s=s.replace(re,rep); return s.trim(); };
const titleTerms=(cfg.people.titles||[]).map(norm).filter(Boolean);
const neverTerms=(cfg.people.never||[]).map(norm).filter(Boolean);
const passesPeople=(title)=>{ const t=norm(title); if(!t) return false; if(neverTerms.some(n=>t.includes(n))) return false; return titleTerms.some(x=>t.includes(x)); };
const tierFor=(firstHire)=>{ for(const t of (cfg.tiers||[])){ if(t.kind==='rest') return t.url; if(t.kind==='first_hire'&&t.value===firstHire) return t.url; } return ''; };

// Companies: Apply ICP rows (company + biz + reason), Contact Calls rows (first hire + bodies).
const companies={};
for(const it of $('Apply ICP').all()){ const j=it.json||{}; if(j.domain) companies[j.domain]=j; }
const calls=$('Contact Calls').all().map(i=>i.json).filter(c=>c&&c.domain);
const callByDomain={}; for(const c of calls) callByDomain[c.domain]=c;

const failed=[];
const out=[];
const seenKey=new Set(); const seenLi=new Set();
const nowIso=new Date().toISOString();
const gate={ checked:0, dropped_never:0, dropped_no_title:0 };
const tiers={};

function baseRow(d){
  const e=companies[d]||{}; const c=e.company||{}; const b=e.biz||{}; const j=c.job||{}; const addr=b.address||{}; const cc=callByDomain[d]||{};
  const firstHire=cc.first_hire||'Unknown';
  const target=tierFor(firstHire);
  return {
    'Domain': d,
    'Company': String(c.company||b.name||'').trim(),
    'company_clean': String(c.company||b.name||'').trim(),
    'Event Type': cfg.event_type,
    'Target Campaign': target,
    'Intent Status': 'NEW',
    'detected_at': nowIso,
    'ICP Reason': e.icp_reason||'',
    'Existing In Role': cc.existing_in_role,
    'First Hire': firstHire,
    'Job ID': j.id||'', 'Job Title': j.title||'', 'Job Link': j.link||'', 'Job Posted': j.posted_at||null,
    'Job Description': j.description||'', 'Job Seniority': j.seniority||'', 'Job Function': j.function||'',
    'Job Employment Type': j.employment_type||'', 'Job Industries': j.industries||'', 'Job Applicants': j.applicants,
    'Job Salary': j.salary||'', 'Job Poster Name': j.poster_name||'', 'Job Poster Title': j.poster_title||'', 'Job Poster LinkedIn': j.poster_linkedin||'',
    'Description': b.description||'', 'Industry Groups': kv(b.industry_groups), 'Employees': b.employees||'',
    'Revenue Range': b.revenue_range||'', 'Score': b.score!=null?String(b.score):'', 'Keywords': b.keywords?Object.keys(b.keywords).join(', '):'',
    'Company Status': b.status?(b.status.status+(b.status.confidence!=null?' ('+b.status.confidence+')':'')):'',
    'Start Date': b.start_date||'', 'Street': addr.street||'', 'Company City': addr.city||'', 'Company State': addr.state||'',
    'Country': addr.country||c.country||'', 'Zip': addr.zip||'',
    'Phones': join(b.phones), 'Public Emails': join(b.public_emails), 'public_emails_clean': '',
    'Social URLs': join(b.social_urls), 'MX Provider': b.mx_provider||'', 'Redirect Domain': b.redirect_domain||'',
    'Email Pattern': patterns[d]||''
  };
}
const patterns={};
function signal(d){ const c=(companies[d]||{}).company||{}; const j=c.job||{}; const cc=callByDomain[d]||{}; return 'Hiring '+(j.title||'a role')+(j.posted_at?' (posted '+j.posted_at+')':'')+' · first hire '+(cc.first_hire||'Unknown')+(cc.existing_in_role!=null?' ('+cc.existing_in_role+' in role today)':'')+'. Job: '+(j.link||''); }
function push(d,p,source){
  const full=String(p.name||'').trim();
  const first=cleanFirst(full), last=cleanLast(full);
  const key=(first.toLowerCase()+last.toLowerCase()+d).trim();
  const li=String(p.linkedin||'').trim();
  if(!key||!first) return 'nokey';
  if(seenKey.has(key)||(li&&seenLi.has(li.toLowerCase()))) return 'dup';
  gate.checked++;
  const t=norm(p.title);
  if(neverTerms.some(n=>t.includes(n))){ gate.dropped_never++; return 'never'; }
  if(!titleTerms.some(x=>t.includes(x))){ gate.dropped_no_title++; return 'notitle'; }
  seenKey.add(key); if(li) seenLi.add(li.toLowerCase());
  const row=Object.assign(baseRow(d), {
    'Name': full, 'first_name': first, 'last_name': last,
    'LinkedIn URL': li, 'Email': String(p.email||'').trim(),
    'Title': String(p.title||'').trim(), 'Seniority': String(p.seniority||'').trim(), 'Department': String(p.department||'').trim(),
    'Phone': p.phone||'', 'City': p.city||'', 'State': p.state||'',
    'Contact Key': key, 'Contact Source': source,
    'Signal Detail': signal(d)+' · '+source+' · '+(p.title||'')
  });
  tiers[row['Target Campaign']]=(tiers[row['Target Campaign']]||0)+1;
  out.push({ json: row });
  return 'ok';
}

// Source 1: ContaGen.
const cg={called:0,matched:0,contacts:0,kept:0,errors:0};
let cgItems=[]; try{ cgItems=$('ContaGen Contacts').all(); }catch(e){}
cgItems.forEach((it,i)=>{
  const call=calls[i]; if(!call||!companies[call.domain]) return;
  cg.called++;
  const r=body(it); const b=parse(r.body);
  if(!(r.status>=200&&r.status<300)||!b||typeof b!=='object'){ cg.errors++; failed.push({ tier:'ContaGen', name:call.domain, reason:'HTTP '+r.status+' '+why(b,r.body) }); return; }
  const entry=(b.results&&(b.results[call.domain]||Object.values(b.results)[0]))||null;
  const contacts=(entry&&entry.contacts)||[];
  if(contacts.length) cg.matched++;
  const pattern=entry&&entry.email_pattern?entry.email_pattern+(entry.email_pattern_confidence!=null?' ('+entry.email_pattern_confidence+')':''):'';
  if(pattern&&!patterns[call.domain]) patterns[call.domain]=pattern;
  const e=companies[call.domain];
  if(entry&&!e.biz) e.biz={ name:entry.name, employees:entry.employees, revenue_range:entry.revenue_range, industry_groups:entry.industry_groups, address:entry.address };
  else if(entry&&e.biz&&!e.biz.revenue_range&&entry.revenue_range) e.biz.revenue_range=entry.revenue_range;
  for(const p of contacts){
    cg.contacts++;
    if(push(call.domain,{ name:p.name, title:p.title, seniority:p.seniority, department:p.department, email:p.email, linkedin:linkedinOf(p.social_urls), phone:firstPhone(p.phone), city:'', state:p.state||'' },'ContaGen')==='ok') cg.kept++;
  }
});

// Source 2: Supersoniq, net-new only.
const sq={called:0,matched:0,contacts:0,kept:0,errors:0,credits:0};
let sqItems=[]; try{ sqItems=$('Supersoniq Contacts').all(); }catch(e){}
sqItems.forEach((it,i)=>{
  const call=calls[i]; if(!call||!companies[call.domain]) return;
  sq.called++;
  const r=body(it); const b=parse(r.body);
  if(!(r.status>=200&&r.status<300)||!b||typeof b!=='object'||b.success===false){ sq.errors++; failed.push({ tier:'Supersoniq', name:call.domain, reason:'HTTP '+r.status+' '+why(b,r.body) }); return; }
  sq.credits+=Number(b.credits_used)||0;
  const comps=Array.isArray(b.results)?b.results:[];
  let any=false;
  for(const comp of comps){
    const contacts=Array.isArray(comp.contacts)?comp.contacts:[comp];
    for(const p of contacts){
      if(!p||!(p.first_name||p.full_name)) continue;
      any=true; sq.contacts++;
      const full=p.full_name||((p.first_name||'')+' '+(p.last_name||'')).trim();
      if(push(call.domain,{ name:full, title:p.job_title, seniority:p.seniority, department:p.function, email:p.email, linkedin:p.linkedin_url, phone:'', city:p.contact_city||'', state:p.contact_region||'' },'Supersoniq')==='ok') sq.kept++;
    }
  }
  if(any) sq.matched++;
});

const companiesWithContact=new Set(out.map(o=>o.json.Domain)).size;
const stats={ companies:Object.keys(companies).length, companies_with_contact:companiesWithContact, contacts:out.length, contagen:cg, supersoniq:sq, people_gate:gate, tiers, failed };
if(!out.length) return [{ json: { _empty:true, _stats:stats } }];
out[0].json._stats=stats;
return out;

// Apply DNC: drops contacts whose domain sits on the client's DNC table, and strips the
// underscore-prefixed carriers (_stats, _empty) so the upsert's auto-map never meets a key
// the table does not have. Build Run Log counts the DNC drop as (rows in) minus (rows out).
// Zero survivors still emit one {_empty} placeholder so the Any After DNC? gate reaches the close.
const dnc=new Set();
try{
  const r=$('Get DNC Domains').first().json||{};
  for(const rec of (r.records||[])){ const f=rec.fields||{}; const d=String(f.Domain||f.domain||'').toLowerCase().trim(); if(d) dnc.add(d); }
}catch(e){}
const out=[];
for(const i of $('Clean Fields').all()){
  const j=i.json||{};
  if(j._empty) continue;
  const d=String(j['Domain']||'').toLowerCase().trim();
  if(dnc.size&&d&&dnc.has(d)) continue;
  const row={};
  for(const k of Object.keys(j)){ if(!k.startsWith('_')) row[k]=j[k]; }
  out.push({ json: row });
}
if(!out.length) return [{ json: { _empty:true } }];
return out;

// A guard tripped before any paid call: the launch payload, the play row, or the client row
// is missing something. One error, the row says exactly what. 'Failed' is the Error Logger's
// word for a crash; a guard trip is Succeeded with errors.
let g={};
try{ const p=$('Parse Play').first().json; if(p&&p.config_ok===false) g=p; }catch(e){}
if(!g.guard){ try{ const l=$('Parse Launch').first().json; if(l&&l.config_ok===false) g=l; }catch(e){} }
let baseMissing=false; if(!g.guard){ try{ const c=$('Client Vars').first().json; if(c&&!c.base){ baseMissing=true; g=Object.assign({},$('Parse Play').first().json,{guard:'client'}); } }catch(e){} }
const what=g.guard==='launch'?'Apify webhook payload':(g.guard==='play'?'play row '+(g.play||''):'client row '+(g.client||''));
const missing=baseMissing?'Clayroots Base ID on the Hub Clients row':((g.missing||[]).join(', ')||'unknown');
const row={
 'Automation':'Handle Intent Signal',
 'Status':'Succeeded with errors',
 'Run at': $now.toISO(),
 'Records In': 0,
 'Records Out': 0,
 'Errors': 1,
 'Target': g.table||'(no table)',
 'Trigger':'event',
 'Execution ID': String($execution.id),
 'Execution Link': 'https://n8n.flowroots.com/workflow/'+$workflow.id+'/executions/'+$execution.id,
 'Description': '**Guard tripped before any paid call, 1 error**\n\n**Where:** '+what+'\n\n**Missing / unreadable:** '+missing+'\n\nThe play row (KB Files, Type intent-play) needs: table, event, companies (country | max N employees | we sell to: ...), people (titles | never ... | N per company), tiers (rule -> url | rest -> url). The Apify payload needs {play, resource}. Fix and rerun.'
};
if(g.client) row['Client']=[g.client];
return [{json:row}];

// Build Run Log: the one row this run writes, per the logging standard. Status computed from
// failed[], skips separated, the Description is the whole funnel. Every node reference is
// guarded: a branch that never ran reads as 0.
const sd=$getWorkflowStaticData('global'); const rs=sd.runStartedAt||0;
let cfg={}; try{ cfg=$('Parse Play').first().json||{}; }catch(e){ try{ cfg=$('Parse Launch').first().json||{}; }catch(e2){} }
let base=''; try{ base=$('Client Vars').first().json.base||''; }catch(e){}
const nf=(x)=>Number(x||0).toLocaleString('en-US');
const failed=[]; const skips=[];

let fq={ jobs_in:0, qualified:0, drops:{} };
try{ const s=$('Filter & Qualify Jobs').first().json._stats; if(s) fq=s; }catch(e){}
const d=fq.drops||{};
const dropLine=['country '+nf(d.country),'staffing '+nf((d.staffing_name||0)+(d.staffing_industry||0)),'body shop '+nf(d.body_shop),'over max employees '+nf(d.headcount),'no domain '+nf(d.no_domain),'duplicate '+nf(d.duplicate),'already in table '+nf(d.worked)].join(' · ');

let bz={ called:0, matched:0, unknown:0, closed:0, errors:0, failed:[] }; let closedList=[];
try{ const f=$('Company Facts').first().json; if(f&&f._stats) bz=f._stats; closedList=(f&&f.closed)||[]; }catch(e){}
for(const f of (bz.failed||[])) failed.push(f);

let icp={ checked:0, yes:0, partial:0, no:0, missing:0, error:'', rejected:[] }; let polls=0;
try{ const s=$('Apply ICP').first().json._stats; if(s) icp=s; }catch(e){}
try{ polls=Number($('Poll Check').last().json.passes)||0; }catch(e){}
if(icp.error) failed.push({ tier:'ICP check', name:'task', reason:icp.error });

let fh={ yes:0, no:0, unknown:0, failed:[] };
try{ const s=$('Contact Calls').first().json._stats; if(s) fh=s; }catch(e){}
for(const f of (fh.failed||[])) failed.push(f);

let bl={ companies:0, companies_with_contact:0, contacts:0, contagen:{}, supersoniq:{}, people_gate:{}, tiers:{}, failed:[] };
try{ const s=$('Build Intent Leads').first().json._stats; if(s) bl=s; }catch(e){}
for(const f of (bl.failed||[])) failed.push(f);
const cg=bl.contagen||{}, sq=bl.supersoniq||{}, pg=bl.people_gate||{};

let cleaned=0; try{ cleaned=$('Clean Fields').all().map(i=>i.json).filter(j=>j&&!j._empty).length; }catch(e){}
let afterDnc=0; try{ afterDnc=$('Apply DNC').all().map(i=>i.json).filter(j=>j&&!j._empty).length; }catch(e){}
const dncDropped=Math.max(0,cleaned-afterDnc);
let upserted=0; const upsertErr=[];
for(const n of ['Upsert by Email','Upsert by Name+Domain']){
  try{ for(const it of $(n).all()){ const j=it.json||{}; if(j&&j.id) upserted++; else if(j&&j.error) upsertErr.push({ tier:'Upsert', name:n, reason:String((j.error&&(j.error.message||j.error))||'upsert failed').slice(0,120) }); } }catch(e){}
}
for(const f of upsertErr) failed.push(f);
const upsertGap=Math.max(0, afterDnc-upserted-upsertErr.length);
if(upsertGap) failed.push({ tier:'Upsert', name:upsertGap+' row(s)', reason:'no record id came back' });
let wfOk=null, wfErrorPages=0;
try{ const w=$('Run Waterfall').first().json||{}; wfOk=!w.error; wfErrorPages=Number(w.errorPages)||0; }catch(e){}
if(afterDnc&&wfOk===false) failed.push({ tier:'Waterfall', name:'batch call', reason:'errored' });
if(wfErrorPages) failed.push({ tier:'Waterfall', name:wfErrorPages+' page(s)', reason:'error pages' });

if(!fq.qualified) skips.push('Skipped (everything after the hard lines, no company survived them)');
if(fq.qualified&&!icp.yes&&!icp.error) skips.push('Skipped (contacts, no company passed the ICP check)');
if(icp.yes&&!bl.contacts) skips.push('Skipped (enrollment, no contact passed the people gate at '+nf(icp.yes)+' companies)');
if(bl.contacts&&!afterDnc) skips.push('Skipped (enrollment, all '+nf(bl.contacts)+' contacts on DNC)');

const errs=failed.length;
const status=errs?'Succeeded with errors':'Succeeded';
const tierLine=Object.entries(bl.tiers||{}).map(([u,n])=>nf(n)+' -> '+(u?u.replace(/^https?:\/\/[^/]+\/audience\/webhook\//,'').replace(/\/pull-in-prospect$/,''):'(no tier)')).join(' · ')||'none';
const rejLines=(icp.rejected||[]).slice(0,10).map(r=>'- '+r.domain+' ('+r.fit+'): '+r.reason);
const lines=[
  '**'+nf(upserted)+' upserted from '+nf(bl.contacts)+' contacts at '+nf(bl.companies_with_contact)+' of '+nf(icp.yes)+' ICP companies, '+errs+' error'+(errs===1?'':'s')+'**',
  '',
  '**Play:** '+(cfg.play_name||cfg.play||'')+' · **Table:** '+(cfg.table||'')+' in '+(base||'')+' · **Event:** '+(cfg.event_type||''),
  '',
  '**Funnel**',
  '- **Jobs scraped:** '+nf(fq.jobs_in),
  '- **Hard lines dropped:** '+dropLine,
  '- **Companies to BizData:** '+nf(fq.qualified)+' · matched '+nf(bz.matched)+' · unknown '+nf(bz.unknown)+' · closed '+nf(bz.closed)+(closedList.length?' ('+closedList.join(', ')+')':'')+' · errors '+nf(bz.errors),
  '- **ICP check:** '+nf(icp.checked)+' checked in '+nf(polls)+' poll'+(polls===1?'':'s')+' · yes '+nf(icp.yes)+' · partial '+nf(icp.partial)+' · no '+nf(icp.no)+(icp.missing?' · no verdict '+nf(icp.missing):''),
  '- **First hire:** yes '+nf(fh.yes)+' · no '+nf(fh.no)+' · unknown '+nf(fh.unknown),
  '- **ContaGen:** '+nf(cg.called)+' calls · '+nf(cg.matched)+' returned people · '+nf(cg.contacts)+' contacts · '+nf(cg.kept)+' kept · '+nf(cg.errors)+' errors',
  '- **Supersoniq:** '+nf(sq.called)+' calls · '+nf(sq.matched)+' returned people · '+nf(sq.contacts)+' contacts · '+nf(sq.kept)+' net-new kept · '+nf(sq.credits)+' credits · '+nf(sq.errors)+' errors',
  '- **People gate:** '+nf(pg.checked)+' checked · dropped '+nf(pg.dropped_never)+' on never terms · dropped '+nf(pg.dropped_no_title)+' on no title match',
  '- **Contacts kept:** '+nf(bl.contacts)+' at '+nf(bl.companies_with_contact)+' companies',
  '- **Tiers:** '+tierLine,
  '- **Cleaned:** '+nf(cleaned)+' · **after DNC:** '+nf(afterDnc)+(dncDropped?' ('+nf(dncDropped)+' on DNC)':''),
  '- **Upserted to intent table:** '+nf(upserted),
  '',
  '**Waterfall batch fired:** '+(afterDnc?(wfOk?'yes (sweeps all rows not done/verifying)':'no / errored'):'not needed'),
  '',
  '**Enrollment:** handled by the daily Add Leads runs'
];
if(rejLines.length) lines.push('','**ICP rejected ('+nf((icp.rejected||[]).length)+')**\n'+rejLines.join('\n')+((icp.rejected||[]).length>10?'\n- ...and '+((icp.rejected||[]).length-10)+' more':''));
if(failed.length) lines.push('','**FAILED ('+failed.length+')**\n'+failed.slice(0,8).map(f=>'- '+f.tier+' · '+(f.name||'?')+': '+(f.reason||'')).join('\n')+(failed.length>8?'\n- ...and '+(failed.length-8)+' more':''));
if(skips.length) lines.push('',skips.join('\n'));
const row={
 'Automation':'Handle Intent Signal',
 'Status':status,
 'Run at': $now.toISO(),
 'Records In': bl.contacts||0,
 'Records Out': upserted,
 'Errors': errs,
 'Target': cfg.table||'',
 'Trigger':'event',
 'Execution ID': String($execution.id),
 'Execution Link': 'https://n8n.flowroots.com/workflow/'+$workflow.id+'/executions/'+$execution.id,
 'Duration s': Math.round(($now.toMillis() - (rs||$now.toMillis()))/1000),
 'Description': lines.join('\n')
};
if(cfg.client) row['Client']=[cfg.client];
return [{json:row}];

let cv=null; try{ cv=$('Client Vars').first().json; }catch(e){}
if(!cv||!cv.clientSlug) return [];
const cfg=$('Parse Play').first().json||{};
let upserted=0;
try{ upserted+=$('Upsert by Email').all().map(i=>i.json).filter(j=>j&&j.id).length; }catch(e){}
try{ upserted+=$('Upsert by Name+Domain').all().map(i=>i.json).filter(j=>j&&j.id).length; }catch(e){}
return [{ json: {
  recordId: cv.clientRecId||cfg.client||'',
  clientSlug: cv.clientSlug||'',
  base: cv.base||'', table: cfg.table||'', campaign_url: cfg.campaign_url||'', sender: cfg.sender||'webhook',
  upserted: upserted
}}];

// Parse Launch: the Apify run webhook. Body: { play: <KB Files record id>, resource: <Apify run> }.
// Nothing else is read from the payload; the play row carries the play. The resource object
// carries the run's dataset (the jobs) and key-value store (the run's INPUT, the search roles).
const sd=$getWorkflowStaticData('global');
sd.runStartedAt=$now.toMillis();
const j=$input.first().json||{};
const q=j.query||{}; const b=j.body||{};
const pick=(k)=>{ const v=(b[k]!==undefined&&b[k]!=='')?b[k]:q[k]; return (v===undefined||v===null)?'':String(v).trim(); };
const res=b.resource||{};
const cfg={
  play: pick('play'),
  datasetId: String(res.defaultDatasetId||''),
  kvStoreId: String(res.defaultKeyValueStoreId||''),
  sender: pick('sender')||'webhook'
};
const missing=[];
if(!/^rec[A-Za-z0-9]{14}$/.test(cfg.play)) missing.push('play (KB Files record id)');
if(!cfg.datasetId) missing.push('resource.defaultDatasetId');
if(!cfg.kvStoreId) missing.push('resource.defaultKeyValueStoreId');
cfg.config_ok=(missing.length===0);
cfg.missing=missing;
cfg.guard='launch';
return [{ json: cfg }];

// Parse Play: the play row (KB Files, Type intent-play) into the run's config. Four lines,
// every one required; a missing or unreadable line stops the run before any paid call.
// Nothing about a client exists in code: country, size cap, ICP sentence, titles, cap, tiers
// all come from this cell. Airtable rich text escapes markdown, so \_ and friends are unescaped.
//
//   table: tblXXXXXXXXXXXXXX
//   event: became_hiring
//   companies: US | max 200 employees | we sell to: <ICP sentence>
//   people: <title terms, comma list> | never <terms, comma list> | <N> per company
//   tiers: first hire = yes -> <url> | first hire = no -> <url> | rest -> <url>
const row=$input.first().json||{};
const f=row.fields||row;
const raw=String(f['Content']||'').replace(/\\([_*#\[\]()~`>\-|])/g,'$1').replace(/\r/g,'');
const clientLink=Array.isArray(f['Client'])?f['Client'][0]:'';
const client=clientLink&&typeof clientLink==='object'?String(clientLink.id||''):String(clientLink||'');
const missing=[];
const lines={};
for(const ln of raw.split('\n')){ const m=ln.match(/^\s*([a-z]+)\s*:\s*(.*)$/i); if(m) lines[m[1].toLowerCase()]=m[2].trim(); }
const need=(k)=>{ if(!lines[k]){ missing.push(k); return ''; } return lines[k]; };
const list=(s)=>String(s||'').split(',').map(x=>x.trim()).filter(Boolean);

if(!client) missing.push('Client link on the play row');
const table=need('table'); if(table&&!/^tbl[A-Za-z0-9]{14}$/.test(table)) missing.push('table (not a tbl id)');
const event=need('event');

// companies: <country> | max <N> employees | we sell to: <sentence>
let country='', maxEmployees=0, icp='';
const comp=need('companies');
if(comp){
  const parts=comp.split('|').map(s=>s.trim());
  for(const p of parts){
    let m;
    if((m=p.match(/^max\s+(\d+)\s+employees$/i))) maxEmployees=Number(m[1]);
    else if((m=p.match(/^we sell to\s*:\s*(.+)$/i))) icp=m[1].trim();
    else if(/^[A-Z]{2}$/.test(p)) country=p;
    else missing.push('companies: unreadable part "'+p+'"');
  }
  if(!country) missing.push('companies: country');
  if(!maxEmployees) missing.push('companies: max N employees');
  if(!icp) missing.push('companies: we sell to');
}

// people: <titles> | never <terms> | <N> per company
let titles=[], never=[], cap=0;
const ppl=need('people');
if(ppl){
  const parts=ppl.split('|').map(s=>s.trim());
  for(const p of parts){
    let m;
    if((m=p.match(/^never\s+(.+)$/i))) never=list(m[1]);
    else if((m=p.match(/^(\d+)\s+per company$/i))) cap=Number(m[1]);
    else if(!titles.length) titles=list(p);
    else missing.push('people: unreadable part "'+p+'"');
  }
  if(!titles.length) missing.push('people: titles');
  if(!cap) missing.push('people: N per company');
}

// tiers: <rule> -> <url> | ... ; rules: first hire = yes|no|unknown, rest
const tiers=[];
const tr=need('tiers');
if(tr){
  for(const p of tr.split('|').map(s=>s.trim())){
    const m=p.match(/^(.+?)\s*->\s*(https?:\/\/\S+)$/i);
    if(!m){ missing.push('tiers: unreadable "'+p+'"'); continue; }
    const rule=m[1].trim().toLowerCase(); const url=m[2];
    let r;
    if(rule==='rest') tiers.push({ kind:'rest', url });
    else if((r=rule.match(/^first hire\s*=\s*(yes|no|unknown)$/))) tiers.push({ kind:'first_hire', value:r[1].charAt(0).toUpperCase()+r[1].slice(1), url });
    else missing.push('tiers: unknown rule "'+rule+'"');
  }
  if(!tiers.some(t=>t.kind==='rest')) missing.push('tiers: no rest rule');
}

const launch=$('Parse Launch').first().json;
return [{ json: {
  play: launch.play, datasetId: launch.datasetId, kvStoreId: launch.kvStoreId, sender: launch.sender,
  play_name: f['Name']||'', client, table, event_type: event,
  country, max_headcount: maxEmployees, icp_text: icp,
  people: { titles, never, cap },
  tiers,
  config_ok: missing.length===0, missing, guard:'play'
}}];

// Company Facts: reads BizData for every company that passed the hard lines, drops the ones
// DiscoLike reports closed, and hands the survivors to the ICP check as ONE list (one task,
// per DiscoLike's own rule). Industry groups are recorded on the row later, never a verdict.
// Emits one item: { domains, icp_text, companies:{domain -> {company row, biz}} }.
const cfg=$('Parse Play').first().json;
const parse=(b)=>{ if(typeof b!=='string') return b; try{ return JSON.parse(b); }catch(e){ return null; } };
const rows=$('Filter & Qualify Jobs').all().map(i=>i.json).filter(c=>c&&c.domain);
let bizItems=[]; try{ bizItems=$('DiscoLike BizData').all(); }catch(e){}
const stats={ called:0, matched:0, unknown:0, closed:0, errors:0, failed:[] };
const companies={};
const closed=[];
rows.forEach((c,i)=>{
  const it=bizItems[i]; const j=(it&&it.json)||{};
  const status=Number(j.statusCode)||0; const b=parse(j.body===undefined?null:j.body);
  stats.called++;
  let biz=null;
  if(status>=200&&status<300&&b&&typeof b==='object'&&(b.domain||b.name)){ biz=b; stats.matched++; }
  else if(status===204||status===404){ stats.unknown++; }
  else { stats.errors++; stats.failed.push({ tier:'BizData', name:c.domain, reason:'HTTP '+status+' '+String((b&&(b.detail||b.error||b.message))||'').slice(0,120) }); }
  if(biz&&biz.status&&biz.status.status==='closed'&&Number(biz.status.confidence||0)>=0.8){ stats.closed++; closed.push(c.domain); return; }
  companies[c.domain]={ company:c, biz };
});
const domains=Object.keys(companies);
const out={ domains, icp_text: cfg.icp_text, companies, closed, _stats: stats };
return [{ json: out }];

// Prep Poll: reads the task id the ICP check returned and starts the poll loop.
// No task id means the check never started: the loop is skipped and every company is
// reported as an ICP error downstream (never passed through as a yes).
const j=$input.first().json||{};
const status=Number(j.statusCode)||0;
let b=j.body; if(typeof b==='string'){ try{ b=JSON.parse(b); }catch(e){ b=null; } }
const taskId=b&&b.task_id?String(b.task_id):'';
if(!taskId) return [{ json: { task_id:'', done:true, results:null, error:'validate/icp HTTP '+status+' '+String((b&&(b.detail||b.error||b.message))||'no task_id').slice(0,120) } }];
return [{ json: { task_id: taskId, done:false, results:null, error:'' } }];

// Poll Check: one pass of the ICP poll loop. Reads the discogen status; done when the task
// completed or failed, or after 20 passes (5 minutes at 15 s), which is reported as an error.
const j=$input.first().json||{};
const status=Number(j.statusCode)||0;
let b=j.body; if(typeof b==='string'){ try{ b=JSON.parse(b); }catch(e){ b=null; } }
const taskId=String(($('Prep Poll').first().json||{}).task_id||'');
const pass=Number($runIndex)||0;
const st=b&&b.status?String(b.status):'';
if(st==='completed') return [{ json: { task_id:taskId, done:true, results:(b.results||{}), error:'', passes:pass+1 } }];
if(st==='failed'||st==='error'||status>=400) return [{ json: { task_id:taskId, done:true, results:null, error:'discogen '+(st||('HTTP '+status))+' '+String((b&&(b.error||b.detail||b.message))||'').slice(0,120), passes:pass+1 } }];
if(pass+1>=20) return [{ json: { task_id:taskId, done:true, results:null, error:'ICP check timed out after '+(pass+1)+' polls', passes:pass+1 } }];
return [{ json: { task_id:taskId, done:false, results:null, error:'', passes:pass+1 } }];

// Apply ICP: only a company the check called `yes` goes on. partial and no are dropped with
// their reason kept for the run log. A check that never completed rejects everything and is
// logged as an error: no company is ever passed through on a missing verdict.
// One row per kept company: { domain, company, biz, icp_reason, icp_confidence }.
const poll=$input.first().json||{};
const facts=$('Company Facts').first().json||{};
const companies=facts.companies||{};
const stats={ checked:0, yes:0, partial:0, no:0, missing:0, error:poll.error||'', rejected:[] };
const out=[];
if(poll.error||!poll.results){
  stats.error=poll.error||'no results';
  return [{ json: { _empty:true, _stats:stats } }];
}
const res=poll.results;
for(const d of Object.keys(companies)){
  const r=res[d]||res[d.replace(/^www\./,'')]||null;
  stats.checked++;
  if(!r){ stats.missing++; stats.rejected.push({ domain:d, fit:'missing', reason:'no verdict returned' }); continue; }
  const fit=String(r.Fit||r.fit||'').toLowerCase();
  const reason=String(r.Reasoning||r.reasoning||'').slice(0,200);
  const conf=String(r.Confidence||r.confidence||'');
  if(fit==='yes'){ stats.yes++; out.push({ json: { domain:d, company:companies[d].company, biz:companies[d].biz, icp_reason:reason, icp_confidence:conf } }); }
  else { if(fit==='partial') stats.partial++; else stats.no++; stats.rejected.push({ domain:d, fit:fit||'?', reason }); }
}
if(!out.length) return [{ json: { _empty:true, _stats:stats } }];
out[0].json._stats=stats;
return out;

// Count Calls: one row per ICP-approved company with the two FREE count requests that answer
// "does this company already employ the role it is hiring for?". The role terms are the
// searches the Apify task ran (read from the run's INPUT), never typed anywhere else.
//   sq: Supersoniq POST /companies/match, filters.job_titles
//   cg_url: DiscoLike GET /contacts/count?domain=&title=...
const parse=(b)=>{ if(typeof b!=='string') return b; try{ return JSON.parse(b); }catch(e){ return null; } };
let roles=[];
try{
  const j=$('Get Run Input').first().json||{};
  const b=parse(j.body===undefined?null:j.body)||{};
  const urls=[].concat(b.urls||[]).join(' ');
  const seen=new Set();
  for(const m of urls.matchAll(/keywords=([^&\s]+)/g)){ const k=decodeURIComponent(m[1].replace(/\+/g,' ')).trim(); if(k&&!seen.has(k.toLowerCase())){ seen.add(k.toLowerCase()); roles.push(k); } }
}catch(e){}
// A role title as a count term: "DevOps Engineer" -> "DevOps", "Site Reliability Engineer" -> "Site Reliability".
const terms=Array.from(new Set(roles.map(r=>r.replace(/\b(engineer|engineering|specialist|developer|lead|manager)\b/ig,'').replace(/\s+/g,' ').trim()).filter(Boolean)));
const out=[];
for(const it of $('Apply ICP').all()){
  const c=it.json||{}; if(!c.domain) continue;
  const q=['domain='+encodeURIComponent(c.domain)].concat(terms.map(t=>'title='+encodeURIComponent(t))).join('&');
  out.push({ json: { domain:c.domain, roles, terms,
    sq:{ companies:[{ domain:c.domain }], filters:{ job_titles: terms } },
    cg_url:'https://api.discolike.com/v1/contacts/count?'+q } });
}
if(!out.length) return [{ json: { _empty:true } }];
return out;

// Contact Calls: one row per ICP-approved company, carrying the first-hire verdict and the
// request bodies for both contact sources, built from the play's people line.
//
// First hire: a source "knows" the company when it answered with a match; the count is the
// highest across the sources that know it. Yes = known and 0; No = known and above 0;
// Unknown = no source knows the company. Never guessed.
const cfg=$('Parse Play').first().json;
const parse=(b)=>{ if(typeof b!=='string') return b; try{ return JSON.parse(b); }catch(e){ return null; } };
const calls=$('Count Calls').all().map(i=>i.json).filter(c=>c&&c.domain);
let sqItems=[], cgItems=[];
try{ sqItems=$('SQ Count').all(); }catch(e){}
try{ cgItems=$('CG Count').all(); }catch(e){}
const stats={ yes:0, no:0, unknown:0, sq_errors:0, cg_errors:0, failed:[] };
const out=[];
calls.forEach((c,i)=>{
  let known=false, count=0;
  const sj=(sqItems[i]&&sqItems[i].json)||{}; const sb=parse(sj.body===undefined?null:sj.body);
  const ss=Number(sj.statusCode)||0;
  if(ss>=200&&ss<300&&sb&&typeof sb==='object'){
    const m=Array.isArray(sb.matched)?sb.matched[0]:(Array.isArray(sb.results)?sb.results[0]:null);
    if(m&&(m.company_id||m.company_name)){ known=true; count=Math.max(count, Number(m.available_contacts)||0); }
  } else if(ss){ stats.sq_errors++; stats.failed.push({ tier:'First hire (Supersoniq)', name:c.domain, reason:'HTTP '+ss+' '+String((sb&&(sb.error||sb.message))||'').slice(0,100) }); }
  const cj=(cgItems[i]&&cgItems[i].json)||{}; const cb=parse(cj.body===undefined?null:cj.body);
  const cs=Number(cj.statusCode)||0;
  const bizKnown=!!(($('Apply ICP').all()[i]||{}).json||{}).biz;
  if(cs>=200&&cs<300&&cb&&typeof cb==='object'&&cb.count!==undefined){ if(bizKnown){ known=true; count=Math.max(count, Number(cb.count)||0); } }
  else if(cs){ stats.cg_errors++; stats.failed.push({ tier:'First hire (DiscoLike)', name:c.domain, reason:'HTTP '+cs+' '+String((cb&&(cb.detail||cb.error))||'').slice(0,100) }); }
  const firstHire=!known?'Unknown':(count===0?'Yes':'No');
  stats[firstHire.toLowerCase()]++;
  const p=cfg.people;
  out.push({ json: {
    domain:c.domain, existing_in_role: known?count:null, first_hire: firstHire,
    cg:{ domain:[c.domain], title:p.titles, negate_title:p.never, has_linkedin:true, max_companies:1, results_by_company:p.cap },
    sq:{ companies:[{ domain:c.domain }], filters:{ job_titles:p.titles, has_linkedin:true }, tier:'full', per_company_limit:p.cap, confirm:true }
  }});
});
if(!out.length) return [{ json: { _empty:true, _stats:stats } }];
out[0].json._stats=stats;
return out;
